// 双通道变量读写(面板source=BaseSource, 规则source=JsExtensions, 统一掩护)
function GV(k,d){try{var v=source.getVariable(k);if(v!=null&&String(v)!='null'&&String(v)!='undefined'&&String(v)!='')return String(v);}catch(e){}try{var v2=source.get(k);if(v2!=null&&String(v2)!='null'&&String(v2)!='undefined'&&String(v2)!='')return String(v2);}catch(e2){}return (d===undefined)?'':d;}
function SV(k,v){var ok=false;try{source.setVariable(k,v);ok=true;}catch(e){}try{source.put(k,v);ok=true;}catch(e2){}return ok;}
function PUB(){return GV('pub','https://jmcomicui.net');}
function BASE(){var u=GV('url','');if(!u){u='https://comic18j-hbd.space';SV('url',u);}u=String(u).replace(/\/+$/,'');if(!/^https?:\/\//.test(u))u='https://'+u;return u;}
function BASEH(){var m=BASE().match(/^https?:\/\/([^\/]+)/);return m?m[1]:'comic18j-hbd.space';}
// 从发布页抓线路: 返回[{name,url,ms}]
function jmLines(force){
  var now=Date.now();
  var cache=GV('lines','');
  var ts=+GV('linesTs',0);
  if(!force&&cache&&now-ts<1800000){try{var c=JSON.parse(cache);if(c.length)return c;}catch(e){}}
  var pub=PUB();
  var h='';
  try{h=String(java.ajax(pub+',{"timeout":15000}'));}catch(e){}
  if(!h){try{h=String(java.ajax('https://jmcomicui.net'+',{"timeout":15000}'));}catch(e2){}}
  var groups=[['china','内地主线路'],['first_line','分流1'],['second_line','分流2'],['international','国际通用(需魔法)'],['southeast_asia','东南亚(需魔法)']];
  var lines=[{name:'发布页',url:pub,ms:-2}];
  for(var i=0;i<groups.length;i++){
    var m=h.match(new RegExp('<div class="'+groups[i][0]+'">[\\s\\S]*?</div>'));
    if(m){
      var spans=(m[0].match(/<span>([^<]+)<\/span>/g))||[];
      for(var q=0;q<spans.length;q++){
        var dom=String(spans[q]).replace(/<\/?span>/g,'').trim();
        if(!dom||dom.indexOf('.')<0)continue;
        var u=/^https?:/.test(dom)?dom:'https://'+dom;
        lines.push({name:groups[i][1],url:u,ms:-1});
      }
    }
  }
  SV('lines',JSON.stringify(lines));SV('linesTs',String(now));
  return lines;
}
// 测速并排序
function jmSpeed(lines){
  for(var i=0;i<lines.length;i++){
    if(lines[i].ms>=0)continue;
    var t0=Date.now();
    try{
      var r=String(java.ajax(lines[i].url+',{"timeout":8000}'));
      lines[i].ms=(String(r).length>5000)?(Date.now()-t0):99999;
    }catch(e){lines[i].ms=99999;}
  }
  lines.sort(function(a,b){return (a.ms<0?99999:a.ms)-(b.ms<0?99999:b.ms);});
  return lines;
}
// ===== 图源(CDN)管理 =====
function CDN(){return GV('cdn','');}
function CDNS(){return ['cdn-msp','cdn-msp2','cdn-msp3'];}
// 测试图片字节长度探测一个cdn前缀是否有效
function cdnOk(prefixHost,path){
  var t0=Date.now();
  try{
    var u='https://'+prefixHost+path;
    var b=java.get(u,{"User-Agent":"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/141.0.0.0 Safari/537.36"},8000);
    if(b==null)return {ms:99999,ok:false};
    var len=b.length;
    return {ms:(Date.now()-t0),ok:len>15000};
  }catch(e){return {ms:99999,ok:false};}
}
// 图源测速: 返回文本行, 自动选最快
function cdnTest(autoPick){
  var host=BASEH();
  var path=GV('cdnPath','');
  if(!path){path='/media/photos/302588/00001.webp';}
  var names=CDNS();
  var best=null;
  var rows=[];
  for(var i=0;i<names.length;i++){
    var r=cdnOk(names[i]+'.'+host,path);
    rows.push(names[i]+': '+((r.ok)?(r.ms+'ms'):'✘不可用'));
    if(r.ok&&(!best||r.ms<best.ms))best={n:names[i],ms:r.ms};
  }
  var cur=CDN();
  if(best&&autoPick){SV('cdn',best.n);cur=best.n;}
  if(best&&autoPick){
    var agreed=(cur===best.n);
  }
  return rows.join(' | ')+(best?(' | ✅最快: '+best.n+' '+best.ms+'ms'):' | ⚠全部不可用将自动');
}
function jmImg(u){
  var cd=CDN();
  if(!cd)return String(u);
  var h=BASEH();
  var s=String(u);
  return s.replace(/cdn-msp\d*\./g,'').replace(/https?:\/\//,'https://'+cd+'.');
}
// ===== 登录/解冻/状态/收藏夹 =====
function _jmHd(referPath){
  var h={};
  h['User-Agent']='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/141.0.0.0 Safari/537.36';
  h['X-Requested-With']='XMLHttpRequest';
  h['Referer']=BASE()+(referPath||'/');
  return h;
}
function _jmPost(path,body,referPath){
  var r=java.post(BASE()+path, body, _jmHd(referPath));
  if(r==null)return '';
  try{return String(r.body());}catch(e){try{return String(r);}catch(e2){return '';}}
}
function _jmUf(){return GV('jmuser','');}
function _jmPf(){
  try{var m=source.getLoginInfo();var o=JSON.parse(m);if(o)return o;}catch(e){}
  return null;
}
function jmLogin(u,p){
  var r='';
  try{r=_jmPost('/login','username='+encodeURIComponent(u)+'&password='+encodeURIComponent(p)+'&id_remember=1&login_remember=1&submit_login=1','/');}catch(e){return {ok:false,msg:'网络错误: '+String(e).substring(0,80)};}
  try{
    var o=JSON.parse(r);
    if(o.status==1||o.status=='1'){SV('jmuser',u);return {ok:true,msg:'✅ 登录成功: '+u};}
    if(o.status==5||o.status=='5')return {ok:false,frozen:true,msg:'❄️ 账号已被冻结, 请在登录界面点【解冻账号】输入验证码'};
    var em='';try{em=String(o.errors||'').replace(/\\u([0-9a-fA-F]{4})/g,function(mm,hh){return String.fromCharCode(parseInt(hh,16));});}catch(e2){}
    return {ok:false,msg:'❌ '+(em||'登录失败')};
  }catch(e){return {ok:false,msg:'异常: '+r.substring(0,60)};}
}
// 解冻: 取验证码→弹窗输入→POST unfreeze→自动登录
function jmUnfreeze(u,p){
  if(!u){u=_jmUf();}
  var o=_jmPf();if(!u&&o)u=o['账号'];if(!p&&o)p=o['密码'];
  if(!u||!p)return '请先填写账号密码';
  var img=BASE()+'/captcha/'+Math.random();
  var code='';
  try{code=String(java.getVerificationCode(img));}catch(e){return '验证码窗口失败: '+String(e).substring(0,60);}
  if(!code||!code.trim())return '验证码为空';
  var body='username='+encodeURIComponent(u)+'&password='+encodeURIComponent(p)+'&verification='+encodeURIComponent(code.trim())+'&id_remember=1&login_remember=1';
  var r='';
  try{r=_jmPost('/ajax/unfreeze_account',body,'/');}catch(e){return '解冻请求失败: '+String(e).substring(0,80);}
  try{
    var oo=JSON.parse(r);
    if(oo.status==1||oo.status=='1'){SV('jmuser',u);var lg=jmLogin(u,p);return '✅ 解冻成功'+(lg.ok?' 并已登录':' 请再点一次登录');}
    var em2='';try{em2=String(oo.msg||'').replace(/\\u([0-9a-fA-F]{4})/g,function(mm,hh){return String.fromCharCode(parseInt(hh,16));}).replace(/<[^>]+>/g,'');}catch(e2){}
    return '解冻失败: '+(em2||r.substring(0,80));
  }catch(e){return '解冻异常: '+r.substring(0,80);}
}
function jmFavName(){
  var fid=GV('jmfid','0');
  var fs=jmFoldersRaw(false);
  for(var i=0;i<fs.length;i++){if(fs[i].fid===fid)return fs[i].name;}
  return '默认收藏夹';
}
// 检查登录状态(用收藏接口探测)
// 检查登录状态: GET /user/favorite(登录态→Profile页, 游客→Login页)。无副作用(旧版POST探测会误收藏检测用album)
function jmChkLogin(){
  var h='';
  try{h=String(java.ajax(BASE()+'/user/favorite,{"timeout":20000}'));}catch(e){return {ok:false,msg:'❌ 检查失败: '+String(e).substring(0,60)};}
  var t=(h.match(/<title>([^<]*?)<\/title>/)||[])[1]||'';
  if(t.indexOf('Login')>=0||t.indexOf('login')>=0){return {ok:false,msg:'❌ 未登录(游客状态)'};}
  if(t.indexOf('Profile')>=0||t.indexOf('漫画收藏')>=0){
    var uname='';
    var m=h.match(/og:title"\s*content="([^"]*?)\s*(?:&#039;)?\s*(?:Profile|\-)/);
    if(!m)m=h.match(/og:title"\s*content="([A-Za-z0-9_@.]+)/);
    if(m)uname=m[1];
    if(!uname||uname==='null')uname=GV('jmuser','');
    if(uname&&uname!=='null'&&uname!=='')SV('jmuser',uname);
    return {ok:true,msg:'✅ 已登录: '+(uname||'账号')};
  }
  return {ok:false,msg:'❌ 未登录(页面异常, 标题: '+t.substring(0,30)+')'};
}
function jmFav(aid,fid){
  var fid2=fid||GV('jmfid','0');
  var r='';
  try{r=_jmPost('/ajax/favorite_album','album_id='+aid+'&fid='+fid2,'/');}catch(e){return '❌ '+String(e).substring(0,60);}
  if(String(r).indexOf('需要登录')>=0||String(r).indexOf('需要登錄')>=0||String(r).indexOf('\\u9700\\u8981')>=0)return '❌ 未登录, 请先在登录界面登录';
  try{
    var o=JSON.parse(r);
    var msg=String(o.msg||'').replace(/\\u([0-9a-fA-F]{4})/g,function(mm,hh){return String.fromCharCode(parseInt(hh,16));}).replace(/<[^>]+>/g,'');
    if(o.status==1||o.status=='1')return '⭐ 已收藏到['+(fid2==='0'?'默认收藏夹':jmFavName())+'] '+(msg?msg.substring(0,30):'');
    return msg?('❌ '+msg.substring(0,40)):'❌ 收藏失败';
  }catch(e){return '❌ 收藏失败';}
}
// ===== 收藏夹(含取消收藏) =====
function jmFoldersRaw(force){
  var now=Date.now();
  var cache=GV('foldersJson','');
  var ts=+GV('foldersTs',0);
  if(!force&&cache&&now-ts<600000){try{var c=JSON.parse(cache);if(c&&c.length)return c;}catch(e){}}
  var uu=GV('jmuser','');
  var out=[{fid:'0',name:'默认收藏夹'}];
  if(!uu){return out;}
  var h='';
  try{h=String(java.ajax(BASE()+'/user/'+encodeURIComponent(uu)+'/favorite/albums,{"timeout":20000}'));}catch(e){}
  if(h){
    var m=h.match(/<select class="user-select" name="movefolder-fid">([\s\S]*?)<\/select>/);
    if(m){
      var re=/<option value="(\d+)"[^>]*>([^<]*)<\/option>/g;var x;
      while((x=re.exec(m[1]))){
        var nm=String(x[2]).trim();
        if(x[1]==='0'&&(nm.indexOf('請選擇')>=0||nm.indexOf('请选择')>=0))continue;
        out.push({fid:x[1],name:nm||('收藏夹'+x[1])});
      }
    }
  }
  SV('foldersJson',JSON.stringify(out));SV('foldersTs',String(now));
  return out;
}
// 收藏状态: 专辑页 class 判据 (fas fa-bookmark=已收藏 / far fa-bookmark=未收藏)
function jmIsFaved(html){
  var h=String(html);
  var i=h.indexOf('id="album_favorite_');
  if(i<0)return false;
  var seg=h.substring(i,i+260);
  return seg.indexOf('fas fa-bookmark')>=0;
}
// 取消收藏
function jmUnfav(aid,fid){
  var uu=GV('jmuser','');
  if(!uu)return '未登录';
  var r='';
  try{r=_jmPost('/ajax/remove_album_playlist','video_id='+aid+'&list=favorites','/user/'+uu+'/favorite/albums');}catch(e){return '取消失败: '+String(e).substring(0,60);}
  var st=0,msg='';
  try{var o=JSON.parse(r);st=o.status;msg=_jmUnesc(String(o.msg||'')).replace(/<[^>]+>/g,'').trim();}catch(e){}
  if(st==1||st=='1'){SV('foldersTs','0');return '已取消收藏';}
  return '取消失败'+(msg?(' '+msg.substring(0,40)):'');
}
// \uXXXX 解码工具
function _jmUnesc(s){
  s=String(s===undefined||s===null?'':s);
  var out='';var i=0;
  while(i<s.length){
    if(s.charAt(i)=='\\'&&s.charAt(i+1)=='u'){
      try{out+=String.fromCharCode(parseInt(s.substring(i+2,i+6),16));i+=6;continue;}catch(e){}
    }
    out+=s.charAt(i);i++;
  }
  return out;
}
// ===== 收藏/取消收藏: 供 useweb onclick 调用 (参数注入, 无闭包) =====
function jmfs(jv,sv,aid,fid){
  // 收藏或取消: 依据当前状态自动 toggle
  var uu='';
  try{uu=String(sv.getVariable('jmuser'));}catch(e){try{uu=String(sv.get('jmuser'));}catch(e2){}}
  if(!uu||uu=='null'||uu=='undefined'||uu==''){jv.longToast('请先到登录界面登录');return;}
  var base='';
  try{base=String(sv.getVariable('url'));}catch(e){try{base=String(sv.get('url'));}catch(e2){}}
  if(!base||base=='null')base='https://comic18j-hbd.space';
  var hd={'User-Agent':'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/141.0.0.0 Safari/537.36','X-Requested-With':'XMLHttpRequest','Referer':base+'/'};
  // 1. 取当前收藏状态
  var cur=false;
  try{
    var ah=String(jv.ajax(base+'/album/'+aid+',{"timeout":20000}'));
    var d=Packages.org.jsoup.Jsoup.parse(ah);
    var fe=d.select('#album_favorite_'+aid);
    // 判据=内层<i>的 fas(实心=已收藏)/far(空心=未收藏); btn-primary 是恒定类名不能当判据
    if(fe.size()>0){cur=String(fe.get(0).html()).indexOf('fas fa-bookmark')>=0;}
  }catch(e){jv.longToast('状态获取失败, 请重试');return;}
  var path=cur?'/ajax/remove_album_playlist':'/ajax/favorite_album';
  var body=cur?('video_id='+aid+'&list=favorites'):('album_id='+aid+'&fid='+fid);
  var r='';
  try{
    var resp=jv.post(base+path,body,hd);
    try{r=String(resp.body());}catch(e2){r=String(resp);}
  }catch(e){jv.longToast('操作失败, 请重试');return;}
  var st=0,msg='';
  try{
    var o=JSON.parse(String(r));st=o.status;msg=String(o.msg||'');
    var z=0;
    while(z<msg.length-5){
      if(msg.charAt(z)=='\\'&&msg.charAt(z+1)=='u'){try{msg=msg.substring(0,z)+String.fromCharCode(parseInt(msg.substring(z+2,z+6),16))+msg.substring(z+6);}catch(e3){z++;}}
      z++;
    }
    msg=msg.replace(/<[^>]+>/g,'').replace(/^[×\s]+/,'').trim();
  }catch(e){
    var rs=String(r);
    if(rs.indexOf('需要登录')>=0||rs.indexOf('需要登錄')>=0){jv.longToast('未登录, 请到登录界面登录');return;}
    jv.longToast('操作失败');return;
  }
  if(st==1||st=='1'){
    jv.longToast(cur?('已从收藏夹移出'):('已收藏到收藏夹['+(fid=='0'?'默认':fid)+'] '+(msg?msg.substring(0,20):'')));
    if(sv.refreshBookInfo)try{sv.refreshBookInfo();}catch(e){}
  } else if(msg.indexOf('需要登录')>=0||msg.indexOf('需要登錄')>=0){
    jv.longToast('未登录, 请到登录界面登录');
  } else {
    jv.longToast(msg?('失败: '+msg.substring(0,40)):'操作失败');
  }
}
