    for(var i2=0;i2<fs.length;i2++){txt+='['+fs[i2].name+'='+fs[i2].fid+'] ';}
    return done(toast(txt));
  }
  // 选定收藏夹 (action 名形如 setfid271800)
  if(action && action.indexOf('setfid')===0){
