// ===== 工具: 列表解析(纯函数, 无网络) =====
function jmAttr(el,names){
  if(!el)return '';
  for(var i=0;i<names.length;i++){
    var v='';
    try{v=String(el.attr(names[i])||'');}catch(e){}
    if(v.length>0)return v;
  }
  return '';
}
function jmAbs(u,host){
  var s=String(u);
  if(!s)return s;
  if(s.indexOf('http')===0)return s;
  if(s.indexOf('//')===0)return 'https:'+s;
  if(s.indexOf('/')===0)return 'https://'+host+s;
  return s;
}
// 解析列表页(搜索/发现通用): 返回 JSON 字符串数组
function jmParseList(html){
  var host=BASEH();
  var doc=Packages.org.jsoup.Jsoup.parse(String(html));
  // 普通页=list-col; 每周连载等页=list-item; 兜底切换防重复
  var cells=doc.select('.list-col');
  if(cells.size()===0){cells=doc.select('.list-item');}
  var out=[];
  for(var i=0;i<cells.size();i++){
    var c=cells.get(i);
    var a=c.selectFirst('a[href^="/album/"],a[href^="/novel/"],a[href^="/video/"],a[href^="/video_cosav/"]');
    if(!a)continue;
    var href=String(a.attr('href')).split('?')[0].split('#')[0];
    var m=href.match(/\/(album|novel|video|video_cosav)\/(\d+)/);
    if(!m)continue;
    var typ=m[1];
    var id=m[2];
    var img=c.selectFirst('img');
    var cover='';
    if(img){cover=jmAttr(img,['data-original','src']);}
    if(cover&&cover.indexOf('blank.jpg')>=0)cover='';
    cover=jmAbs(cover,host);
    var name='';
    var tt=c.select('.video-title,.dx-title');
    if(tt.size()>0){name=String(tt.get(0).text()).trim();}
    if(!name&&img){name=jmAttr(img,['title','alt']).trim();}
    if(!name){var at=a.attr('title');name=at?String(at).trim():'';}
    var author='';
    var tr=c.select('.title-truncate');
    // 作者行特征: 含 main_tag=2 作者链接, 或文本以"作者:"开头; 无则留空(不再回退书名)
    var auRows=tr;
    for(var ai=0;ai<auRows.size();ai++){
      var elA=auRows.get(ai);
      var ling=elA.select('a');
      var hits=0;
      for(var a2=0;a2<ling.size();a2++){var h2=String(ling.get(a2).attr('href')||'');if(h2.indexOf('main_tag=2')>=0)hits++;}
      var tA=String(elA.text()).replace(/[\s\u00a0]+/g,' ').trim();
      if(hits>0||/^作者[:：]/.test(tA)){
        var names=[];
        for(var a3=0;a3<ling.size();a3++){var nn=String(ling.get(a3).text()).trim();if(nn&&names.indexOf(nn)<0)names.push(nn);}
        if(names.length){author=names.join(', ');}
        else{author=tA.replace(/^作者[:：]\s*/,'').trim();}
        break;
      }
    }
    var kind='';
    var lc=c.select('.label-category');
    if(lc.size()>0){kind=String(lc.get(0).text()).trim();}
    if(!kind){var vk=c.select('.video-keywords');if(vk.size()>0){kind=String(vk.get(0).text()).replace(/分类标签[:：]/,'').trim();}}
    var wordCount='';
    var ws=c.select('[id*=likes]');
    if(ws.size()>0){wordCount=String(ws.get(0).text()).trim();}
    var intro='';
    if(tr.size()>2){intro=String(tr.get(tr.size()-1).text()).trim();}
    out.push(String(JSON.stringify({name:name,author:author,kind:kind,coverUrl:cover,bookUrl:'https://'+host+href,wordCount:wordCount,intro:intro,id:id})));
  }
  return out;
}
