function jmChapters(){
  var host=BASEH();
  var base=BASE();
  var doc=Packages.org.jsoup.Jsoup.parse(String(result));
  var out=[];
  if(/\/(video|video_cosav)\//.test(baseUrl)){
    book.type=4;
    return [String(JSON.stringify({text:(book.name||'视频'),url:baseUrl}))];
  }
  if(/\/novel\//.test(baseUrl)){
    book.type=8;
    var as=doc.select('a[href*="/novelchapters/"]');
    for(var i=0;i<as.size();i++){
      var href=String(as.get(i).attr('href')).split('?')[0];
      if(!/^\/novelchapters\/\d+/.test(href))continue;
      var txt=String(as.get(i).text()).trim();
      if(!txt)continue;
      var u='https://'+host+href;
      if(out.length&&out[out.length-1]===u)continue;
      out.push(String(JSON.stringify({text:txt,url:u})));
    }
    return out;
  }
  // album: 系列数据(带data-index的album链接) 优先; 否则 .reading 单章; 最后兜底 /photo/{albumId}
  book.type=64;
  var epi=doc.select('a[data-index][href*="/album/"]');
  if(epi.size()>1){
    var arr=[];
    for(var e=0;e<epi.size();e++){
      var ah=String(epi.get(e).attr('href')).split('?')[0];
      var m0=ah.match(/\/album\/(\d+)/);
      if(!m0)continue;
      var itx=+String(epi.get(e).attr('data-index'))||e;
      arr.push({idx:itx,text:String(epi.get(e).text()).trim()||('第'+(e+1)+'话'),url:'https://'+host+'/photo/'+m0[1]});
    }
    arr.sort(function(x,y){return x.idx-y.idx;});
    for(var z=0;z<arr.length;z++)out.push(String(JSON.stringify({text:arr[z].text,url:arr[z].url})));
    return out;
  }
  var aim='';
  var am=String(baseUrl).match(/\/(album|photo)\/(\d+)/);
  if(am)aim=am[2];
  var rd=doc.select('a.reading');
  if(rd.size()>0){
    var rh=String(rd.get(0).attr('href')).split('?')[0];
    var rm=rh.match(/\/photo\/(\d+)/);
    if(rm){
      out.push(String(JSON.stringify({text:'开始阅读',url:'https://'+host+'/photo/'+rm[1]})));
      return out;
    }
  }
  var ph=doc.select('a[href*="/photo/"]');
  var seen={};
  for(var p=0;p<ph.size();p++){
    var hh=String(ph.get(p).attr('href')).split('?')[0];
    if(!/^\/photo\/\d+/.test(hh))continue;
    if(aim){
      var mm2=hh.match(/\/photo\/(\d+)/);
      if(!mm2||mm2[1]!==aim)continue;
    }
    if(seen[hh])continue;seen[hh]=1;
    var tt=String(ph.get(p).text()).trim();
    if(!tt)tt='开始阅读';
    out.push(String(JSON.stringify({text:tt,url:'https://'+host+hh})));
  }
  if(out.length===0&&aim){
    out.push(String(JSON.stringify({text:'开始阅读',url:'https://'+host+'/photo/'+aim})));
  }
  return out;
}
