function jmContent(){
  var host=BASEH();
  var doc=Packages.org.jsoup.Jsoup.parse(String(result));
  // 视频: 提取 m3u8
  if(/\/(video|video_cosav)\//.test(baseUrl)){
    var srcs=doc.select('source[type*=mpegURL],source[src*=m3u8]');
    if(srcs.size()>0){
      var mu=String(srcs.get(0).attr('src'));
      return mu;
    }
    var mm=String(result).match(/https?:\/\/[^"'\s]*m3u8[^"'\s]*/);
    if(mm)return mm[0];
    return '视频地址获取失败，请刷新重试';
  }
  // 小说
  if(/\/novelchapters\//.test(baseUrl)){
    var ncs=doc.select('div.novel-content[id^=ncc]');
    if(ncs.size()>0){
      var parts=[];
      for(var nx=0;nx<ncs.size();nx++){
        var nh=String(ncs.get(nx).html()).trim();
        if(nh)parts.push(nh);
      }
      if(parts.length)return parts.join('\n');
    }
    var nc1=doc.select('.novel-content');
    if(nc1.size()>0){var nh1=String(nc1.get(nc1.size()-1).html()).trim();if(nh1)return nh1;}
    return '小说内容为空';
  }
  // 漫画: 图片 (只保留正文图 /media/photos/{id}/)
  var imgs=doc.select('img[data-original]');
  var lines=[];
  var pid='';
  var pm=String(baseUrl).match(/\/photo\/(\d+)/);
  if(pm)pid=pm[1];
  for(var i=0;i<imgs.size();i++){
    var u=String(imgs.get(i).attr('data-original'));
    if(!u)continue;
    if(u.indexOf('/media/photos/')<0)continue;
    if(pid&&u.indexOf('/media/photos/'+pid+'/')<0)continue;
    u=jmAbs(u,host);
    lines.push('<img src="'+jmImg(u)+'">');
  }
  if(lines.length===0){
    var all=doc.select('img[src]');
    for(var q=0;q<all.size();q++){
      var us=String(all.get(q).attr('src'));
      if(us.indexOf('/media/photos/')>=0){lines.push('<img src="'+jmImg(jmAbs(us,host))+'">');}
    }
  }
  if(lines.length===0)return '未获取到图片，请稍后重试';
  return lines.join('\n');
}
