  try{base=String(sv.getVariable('url'));}catch(e){try{base=String(sv.get('url'));}catch(e2){}}
  if(!base||base=='null')base='https://comic18j-hbd.space';
  var hd={'User-Agent':'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/141.0.0.0 Safari/537.36','X-Requested-With':'XMLHttpRequest','Referer':base+'/'};
  var cur=false;
  try{
    var ah=String(jv.ajax(base+'/album/'+aid+',{"timeout":20000}'));
