  }catch(e){jv.longToast('操作失败, 请重试');return;}
  var st=0,msg='';
  try{
    var o=JSON.parse(String(r));st=o.status;msg=String(o.msg||'');
    var z=0;
    while(z<msg.length-5){
      if(msg.charAt(z)=='\\'&&msg.charAt(z+1)=='u'){try{msg=msg.substring(0,z)+String.fromCharCode(parseInt(msg.substring(z+2,z+6),16))+msg.substring(z+6);}catch(e3){z++;}}
      z++;
    }
    msg=msg.replace(/<[^>]+>/g,'').replace(/^[×\s]+/,'').trim();
  }catch(e){
    var rs=String(r);
    if(rs.indexOf('需要登录')>=0||rs.indexOf('需要登錄')>=0){jv.longToast('未登录, 请到登录界面登录');return;}
    jv.longToast('操作失败');return;
  }
  if(st==1||st=='1'){
    jv.longToast(cur?('已从收藏夹移出 '+(msg?msg.substring(0,16):'')):('已收藏到收藏夹['+fid+'] '+(msg?msg.substring(0,16):'')));
  } else if(msg.indexOf('需要登录')>=0||msg.indexOf('需要登錄')>=0){
    jv.longToast('未登录, 请到登录界面登录');
  } else {
